type Calculation={consumption_bases?:ConsumptionBasis[];id:string;captured_at:string;extraction_started_at?:string;source_articles:number;summary:Record<string,number|null>;filters:Filters;temporary_parameters:Params};
type Job={sequential_delegations?:boolean;id:string;filters:Filters;temporary_parameters:Params;status:'QUEUED'|'RUNNING'|'COMPLETED'|'FAILED';phase:string;progress:number;total_articles:number;processed_articles:number;total_batches:number;completed_batches:number;batch_size:number;error:string|null;result:Calculation|null};
const jobActive=(job:Job|null)=>!!job&&['QUEUED','RUNNING'].includes(job.status);
type StockAlert={code:'NONE'|'NO_STOCK'|'INSUFFICIENT'|'UNKNOWN';label:string};
type Row={incoming_exit?:number;outgoing_exit?:number;incoming_transit?:number;outgoing_transit?:number;interchanges_included?:boolean;consumption_method?:string;stock_alert?:StockAlert;id:number;sku:string;description:string;delegation:string;unit_type:string;unit_source?:string;stock:number|null;incoming:number|null;outgoing:number|null;inventory_position:number|null;monthly_mean:number;monthly_consumption:{month:string;observed_days:number;calendar_days:number;consumption:number;sold?:number;returned?:number;daily_mean?:number;monthly_consumption:number;estimated:boolean}[];daily_mean:number;daily_reference?:number;spot_analysis?:SpotSummary;exceptionality?:ConsumptionExceptionality;statistic_available?:boolean;daily_std:number;gross_sales:number;returns:number;observed_days:number;total_demand:number;safety_stock:number;minimum_stock:number;maximum_stock:number;replenishment_point:number;target_stock:number;final_quantity:number;quantity_without_multiple?:number;quantity_with_exit_multiple?:number|null;exit_multiple?:number|null;central_covers_without_multiple?:boolean|null;central_covers_with_exit_multiple?:boolean|null;central_total_without_multiple?:number|null;central_total_with_exit_multiple?:number|null;effective_multiple:number|null;parameters:Params;overstock:boolean;excess_stock:number;no_consumption:boolean;central_stock:number|null;central_incoming:number|null;central_outgoing:number|null;central_physical_available:number|null;central_monthly_consumption:number|null;central_daily_std:number|null;central_reserve:number|null;central_reserve_days:number;central_available:number|null;central_total_requested:number;central_can_supply:boolean;central_shortage:number|null;recommendations:{code:string;reason:string}[];calculation:{z:number;window_start:string;window_end:string}};
const base='/api/v1/store/replenishment';
const fmt=(n:number|null|undefined)=>n==null?'Sin datos':n.toLocaleString('es-ES',{maximumFractionDigits:3});
const fmtExcess=(n:number)=>n.toLocaleString('es-ES',{maximumFractionDigits:0});
const fmtTarget=(n:number)=>Math.ceil(n).toLocaleString('es-ES',{maximumFractionDigits:0});
const fmtDispatch=(n:number|null|undefined)=>n==null?'Sin datos':Math.floor(n).toLocaleString('es-ES',{maximumFractionDigits:0});
const fmtMonthly=(n:number)=>n.toLocaleString('es-ES',{maximumFractionDigits:0});
const sortFields=[['sku', 'Código'], ['description', 'Descripción'], ['delegation', 'Delegación'], ['stock', 'Stock'], ['incoming', 'Entrada +Trans'], ['outgoing', 'Salida +Trans'], ['inventory_position', 'Disponible previsto'], ['monthly_mean', 'Consumo mensual'], ['exceptionality', 'Flag'], ['minimum_stock', 'Mínimo'], ['replenishment_point', 'Punto de reposición'], ['maximum_stock', 'Máximo'], ['quantity_without_multiple', 'Reposición base'], ['quantity_with_exit_multiple', 'Reposición con múltiplos'], ['exit_multiple', 'Múltiplo EXIT'], ['central_available', 'Almeiras · despachable'], ['central_physical_available', 'Almeiras · stock disponible'], ['alerts', 'Avisos'], ['coverage', 'Cobertura']];
const time=(s:string)=>new Date(s).toLocaleString('es-ES',{timeZone:'Europe/Madrid'});
const initial:Params={consumption_basis:'MEAN',target_mode:'POINT',review_days:7,maximum_days:30,lead_days:1,use_safety_stock:true,service_level:95,central_reserve_days:7,multiple_mode:'NONE',exclude_no_consumption:true,simple_formula:true};
async function responseBody(res:Response){const text=await res.text();let body;try{body=JSON.parse(text)}catch{throw Error(res.ok?'La respuesta del servidor no es válida. Inténtalo de nuevo.':`El servidor no pudo completar la operación (${res.status}). Inténtalo de nuevo; si persiste, revisa el registro del servidor.`)}if(!res.ok)throw Error(typeof body.detail==='string'?body.detail:'No se pudo completar la operación. Revisa la conexión con EXIT.');return body}
async function api<T>(path:string,options:RequestInit={}):Promise<T>{const res=await fetch(base+path,{...options,credentials:'include',headers:{'Content-Type':'application/json',...options.headers}});if(res.status===401)window.dispatchEvent(new Event('session-expired'));return responseBody(res)}
const post=(data:unknown)=>({method:'POST',body:JSON.stringify(data)});
export default function Replenishment(){
 const [tab,setTab]=useState<'calculation'|'redistribution'|'procurement'>('calculation'),[savedOpened,setSavedOpened]=useState(false),[purchaseOpened,setPurchaseOpened]=useState(false);
 function changeTab(value:'calculation'|'redistribution'|'procurement'){setTab(value);setSelected(null);if(value==='redistribution')setSavedOpened(true);if(value==='procurement')setPurchaseOpened(true)}
 const [options,setOptions]=useState<Options|null>(null),[limit,setLimit]=useState(''),[params,setParams]=useState<Params>(initial);
 const [filters,setFilters]=useState<Filters>({date_from:'2026-01-01',date_to:new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid'}).format(new Date()),delegations:['01','02','04','05'],area_id:null,family_id:null,subfamily_id:null,type_id:null,skus:[]});
 const [calculation,setCalculation]=useState<Calculation|null>(null),[rows,setRows]=useState<Row[]>([]),[total,setTotal]=useState(0),[page,setPage]=useState(1),[search,setSearch]=useState(''),[needed,setNeeded]=useState(false),[centralCoverage,setCentralCoverage]=useState('ALL'),[overstockOnly,setOverstockOnly]=useState(false),[minimumMonthly,setMinimumMonthly]=useState(0),[consumption,setConsumption]=useState('ALL'),[sort,setSort]=useState('sku'),[descending,setDescending]=useState(false);
 const [stockAlertFilter,setStockAlertFilter]=useState('ALL');
 const [maximumMonthly,setMaximumMonthly]=useState(''),[exceptionalityFlags,setExceptionalityFlags]=useState<string[]>([]),[salesPeriod,setSalesPeriod]=useState('ALL');
 const invalidConsumptionRange=maximumMonthly!==''&&Number(maximumMonthly)<minimumMonthly;
 const [resultDelegation,setResultDelegation]=useState<string|null>(null),[resultBasis,setResultBasis]=useState<ConsumptionBasis>('MEAN');
 useEffect(()=>{if(calculation){setResultBasis(calculation.consumption_bases?.includes('MEAN')?'MEAN':calculation.temporary_parameters.consumption_basis||'MEAN');if(calculation.filters.delegations.length===1)setResultDelegation(calculation.filters.delegations[0]);setSelected(null)}},[calculation?.id]);
 const [summary,setSummary]=useState<Record<string,number>|null>(null),[exporting,setExporting]=useState(false);
 const restoredSelection=useRef(false);
 const [job,setJob]=useState<Job|null>(null),[restoring,setRestoring]=useState(true);
 const [exportMode,setExportMode]=useState('simple');
 const [busy,setBusy]=useState(false),[loadingRows,setLoadingRows]=useState(false),[phase,setPhase]=useState(''),[error,setError]=useState(''),[message,setMessage]=useState(''),[selected,setSelected]=useState<Row|null>(null),[dirty,setDirty]=useState(false);
 useEffect(()=>{let active=true;api<Options>('/options').then(data=>{if(active){setOptions(data);setLimit(String(data.article_limit));if(!restoredSelection.current)setFilters(old=>({...old,...salesPeriodDates('ALL',data.server_date)}))}}).catch(e=>{if(active)setError(e.message)});return()=>{active=false}},[]);
 useEffect(()=>{let active=true;api<{job:Job|null;latest_result:Calculation|null}>('/jobs/current').then(data=>{if(!active)return;setJob(data.job);const saved=data.job||data.latest_result;if(saved){restoredSelection.current=true;setFilters(saved.filters);setSalesPeriod('CUSTOM');setParams({...initial,...saved.temporary_parameters})}if(data.latest_result)setCalculation(data.latest_result);setDirty(data.job?.status==='FAILED');if(jobActive(data.job))setBusy(true)}).catch(e=>{if(active)setError(e.message)}).finally(()=>{if(active)setRestoring(false)});return()=>{active=false}},[]);
 const progressBusy=useRef(false);
 async function pollJob(signal:AbortSignal){if(!jobActive(job)||progressBusy.current)return;progressBusy.current=true;try{
   const next=await api<Job>(`/jobs/${job!.id}`,{signal});if(signal.aborted)return;setJob(next);setPhase(next.phase);setError('');
   if(next.status==='COMPLETED'){setBusy(false);setPhase('');if(next.result){setCalculation(next.result);setResultDelegation(null);setPage(1);setSelected(null);setDirty(false)}setMessage('Cálculo terminado. Se muestran todos los bloques guardados.')}
   else if(next.status==='FAILED'){setBusy(false);setPhase('');setError(next.error||'El cálculo no terminó. El resultado anterior sigue disponible.')}
 }catch{if(!signal.aborted)setError('No se pudo actualizar el progreso. El cálculo continúa en el servidor; volveremos a consultar automáticamente.')}finally{progressBusy.current=false}}
 useEffect(()=>{if(!jobActive(job))return;const controller=new AbortController();void pollJob(controller.signal);return()=>controller.abort()},[job?.id]);
 useAutoRefresh(pollJob,jobActive(job),job?.id);
 useEffect(()=>{setPage(1)},[search,needed,centralCoverage,overstockOnly,consumption,sort,descending,minimumMonthly,maximumMonthly,exceptionalityFlags,resultDelegation,resultBasis,stockAlertFilter]);
 useEffect(()=>{if(!calculation)return;if(invalidConsumptionRange){setSummary(null);setRows([]);setTotal(0);setLoadingRows(false);return}const controller=new AbortController();setLoadingRows(true);setSummary(null);setRows([]);setSelected(null);const timer=setTimeout(()=>{const query=resultQuery();query.set('page',String(page));api<{items:Row[];total:number;summary:Record<string,number>}>(`/simulations/${calculation.id}/results?${query}`,{signal:controller.signal}).then(data=>{setRows(data.items);setTotal(data.total);setSummary(data.summary)}).catch(e=>{if(!controller.signal.aborted)setError(e.message)}).finally(()=>{if(!controller.signal.aborted)setLoadingRows(false)})},180);return()=>{clearTimeout(timer);controller.abort()}},[calculation?.id,resultDelegation,resultBasis,page,search,needed,centralCoverage,overstockOnly,consumption,sort,descending,minimumMonthly,maximumMonthly,exceptionalityFlags,stockAlertFilter]);
 function changeParams(patch:Partial<Params>){setParams(current=>({...current,...patch}));setDirty(true)}
 function changeFilters(patch:Partial<Filters>){setFilters(current=>({...current,...patch}));setDirty(true)}
 function period(value:string){setSalesPeriod(value);if(value!=='CUSTOM')changeFilters(salesPeriodDates(value,options?.server_date||new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid'}).format(new Date())))}
 async function run(){setBusy(true);setError('');setMessage('');try{
  if(!Number.isInteger(params.review_days)||params.review_days<1||params.review_days>90)throw Error('Indica entre 1 y 90 días para la próxima reposición.');
  if(!Number.isInteger(params.maximum_days)||params.maximum_days<params.review_days||params.maximum_days>1095)throw Error('Los días de stock máximo deben ser al menos los días de reposición y como máximo 1.095.');
  if(!Number.isInteger(params.lead_days)||params.lead_days<0||params.lead_days>180)throw Error('Indica un plazo de llegada de 0 a 180 días.');
  if(!Number.isFinite(params.service_level)||params.service_level<50||params.service_level>99.9)throw Error('Indica un nivel de servicio de 50 a 99,9 %.');
  if(!Number.isInteger(params.central_reserve_days)||params.central_reserve_days<1||params.central_reserve_days>365)throw Error('Indica entre 1 y 365 días de reserva para Almeiras.');
  setSelected(null);setPhase('Enviando cálculo al servidor…');
  const queued=await api<Job>('/jobs',post({filters,all_consumption_bases:true,sequential_delegations:true,temporary_parameters:{...params,consumption_basis:'MEAN',multiple_mode:"NONE"}}));setJob(queued);
  setMessage('El cálculo se guarda por bloques de hasta 1.000 artículos. Puedes salir de esta pantalla y volver para consultar el avance.');
 }catch(e){setError((e as Error).message);setBusy(false);setPhase('')}}
 async function saveLimit(){setBusy(true);setError('');try{const result=await api<{article_limit:number}>('/settings',{method:'PUT',body:JSON.stringify({article_limit:Number(limit)})});setOptions(current=>current?{...current,article_limit:result.article_limit}:current);setMessage('Límite de artículos guardado.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function download(){if(!calculation)return;setExporting(true);setError('');try{const res=await fetch(`${base}/simulations/${calculation.id}/export.xlsx?${resultQuery()}&mode=${exportMode}`,{credentials:'include'});if(res.status===401)window.dispatchEvent(new Event('session-expired'));if(!res.ok||!res.headers.get('content-type')?.includes('spreadsheetml')){await responseBody(res);throw Error('No se recibió un archivo Excel válido.')}const url=URL.createObjectURL(await res.blob());const link=document.createElement('a');link.href=url;link.download='reposicion.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){setError((e as Error).message)}finally{setExporting(false)}}
 function changeSort(key:string){if(sort===key)setDescending(value=>!value);else{setSort(key);setDescending(false)}}
 function sortButton(key:string,label:string){return <button type="button" className="repl-sort-button" aria-label={`Ordenar por ${sortFields.find(([value])=>value===key)?.[1]||label}`} data-direction={sort===key?(descending?'desc':'asc'):undefined} onClick={()=>changeSort(key)}>{label}</button>}
 function resultQuery(){return new URLSearchParams({consumption_basis:resultBasis,...resultDelegation?{delegation:resultDelegation}:{},q:search,needed_only:String(needed),central_coverage:centralCoverage,stock_alert:stockAlertFilter,overstock_only:String(overstockOnly),consumption,sort,descending:String(descending),minimum_monthly_consumption:String(Number.isFinite(minimumMonthly)?Math.max(0,minimumMonthly):0),...maximumMonthly!==''?{maximum_monthly_consumption:maximumMonthly}:{},...exceptionalityFlags.length?{exceptionality_flags:exceptionalityFlags.join(',')}:{}})}
 function openSaved(value:SavedCalculation){setTab('calculation');setCalculation(value as unknown as Calculation);setResultDelegation(value.delegation);setFilters(value.filters);setSalesPeriod('CUSTOM');setParams({...initial,...value.temporary_parameters} as Params);setPage(1);setSelected(null);setDirty(false);setSearch('');setNeeded(false);setCentralCoverage('ALL');setOverstockOnly(false);setConsumption('ALL');setMinimumMonthly(0);setMaximumMonthly('');setExceptionalityFlags([]);setStockAlertFilter('ALL');setMessage(`Cálculo guardado · ${value.delegation_name}`)}
 const nodes=options||{areas:[],families:[],subfamilies:[],types:[],delegations:[]};
 return <section className="page replenishment-page"><header className="section-heading"><div><span className="eyebrow">LOGÍSTICA</span><h1>Cálculo de reposición</h1><p>Consumo y stock de las delegaciones, incluido Almeiras, y disponibilidad para abastecerlas.</p></div><span className="status">No genera pedidos ni modifica EXIT</span></header>{error&&<p className="error" role="alert">{error}</p>}{message&&<p className="repl-notice" role="status">{message}</p>}
 <div className="repl-tabs" role="tablist" aria-label="Opciones de reposición" onKeyDown={event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=['calculation','redistribution','procurement'] as const;const value=event.key==='Home'?tabs[0]:event.key==='End'?tabs[2]:tabs[(tabs.indexOf(tab)+(event.key==='ArrowRight'?1:2))%3];changeTab(value);document.getElementById(`repl-tab-${value}`)?.focus()}}}>
 <button id="repl-tab-calculation" role="tab" aria-selected={tab==='calculation'} aria-controls="repl-panel-calculation" tabIndex={tab==='calculation'?0:-1} className={tab==='calculation'?'active':''} onClick={()=>changeTab('calculation')}>Cálculo de reposición</button>
 <button id="repl-tab-redistribution" role="tab" aria-selected={tab==='redistribution'} aria-controls="repl-panel-redistribution" tabIndex={tab==='redistribution'?0:-1} className={tab==='redistribution'?'active':''} onClick={()=>changeTab('redistribution')}>Redistribución</button>
 <button id="repl-tab-procurement" role="tab" aria-selected={tab==='procurement'} aria-controls="repl-panel-procurement" tabIndex={tab==='procurement'?0:-1} className={tab==='procurement'?'active':''} onClick={()=>changeTab('procurement')}>Aprovisionamiento</button>
 </div>
 <div id="repl-panel-calculation" role="tabpanel" aria-labelledby="repl-tab-calculation" hidden={tab!=='calculation'}>
 <section className="panel repl-controls"><fieldset className="repl-inputs" disabled={busy||restoring}><h2>1. Qué artículos y ventas analizar</h2><p className="small">Solo se incluyen materiales de las categorías visibles configuradas en «Categorías e imágenes», con sus familias. «Todas» significa todas las categorías permitidas. Los cambios en categorías se aplican al iniciar un nuevo cálculo. El periodo selecciona las ventas y devoluciones usadas para obtener el consumo. Se incluyen los días sin ventas. El stock se consulta al calcular; las fechas no programan envíos. Selecciona Almeiras para calcular su consumo propio y consultar su stock.</p><div className="repl-filters"><label>Delegación<select value={filters.delegations.length===5?'ALL_WITH_CENTRAL':filters.delegations.length===4&&!filters.delegations.includes('00')?'ALL':filters.delegations[0]} onChange={e=>changeFilters({delegations:e.target.value==='ALL'?['01','02','04','05']:e.target.value==='ALL_WITH_CENTRAL'?['00','01','02','04','05']:[e.target.value]})}><option value="ALL">Las cuatro delegaciones · una después de otra</option><option value="ALL_WITH_CENTRAL">Todas, incluido Almeiras · una después de otra</option>{nodes.delegations.map(row=><option key={row.code} value={row.code}>{row.name}</option>)}</select></label>{(['area','family','subfamily','type'] as const).map((key,index)=>{const field=`${key}_id` as 'area_id'|'family_id'|'subfamily_id'|'type_id';const lists=[nodes.areas,nodes.families.filter(row=>!filters.area_id||row.area_id===filters.area_id),nodes.subfamilies.filter(row=>!filters.family_id||row.family_id===filters.family_id),nodes.types.filter(row=>!filters.subfamily_id||row.subfamily_id===filters.subfamily_id)];return <label key={key}>{['Área','Familia','Subfamilia','Tipo'][index]}<select value={filters[field]??''} onChange={e=>changeFilters({[field]:e.target.value?Number(e.target.value):null,...index===0?{family_id:null,subfamily_id:null,type_id:null}:index===1?{subfamily_id:null,type_id:null}:index===2?{type_id:null}:{}})}><option value="">Todas</option>{lists[index].map(row=><option key={row.id} value={row.id}>{row.name}</option>)}</select></label>})}<label>Códigos (separados por coma)<input value={filters.skus.join(',')} onChange={e=>changeFilters({skus:e.target.value.split(',')})} placeholder="03009, 41904"/></label><label>Periodo de ventas<select aria-label="Periodo de ventas" value={salesPeriod} onChange={e=>period(e.target.value)}><option value="ALL">Desde 01/01/2026</option>{[30,60,90,180].map(n=><option key={n} value={n}>Últimos {n} días</option>)}<option value="YEAR">Último año</option><option value="CUSTOM">Fechas personalizadas</option></select></label><label>Ventas desde<input type="date" aria-label="Ventas desde" disabled={salesPeriod!=='CUSTOM'} max={filters.date_to} value={filters.date_from} onChange={e=>changeFilters({date_from:e.target.value})}/></label><label>Ventas hasta<input type="date" aria-label="Ventas hasta" disabled={salesPeriod!=='CUSTOM'} min={filters.date_from} max={options?.server_date} value={filters.date_to} onChange={e=>changeFilters({date_to:e.target.value})}/></label></div>
 <h2>2. Cómo calcular</h2><p className="small">Se guardarán las tres propuestas: media, mediana y moda. Después podrás consultarlas con los filtros del resultado, sin volver a calcular.</p><div className="repl-parameter-grid"><label>Objetivo de reposición<select value={params.target_mode} onChange={e=>changeParams({target_mode:e.target.value as Params['target_mode']})}><option value="POINT">Punto de reposición</option><option value="MAXIMUM">Stock máximo</option></select></label><NumberField label="Días hasta la próxima reposición" value={params.review_days} min={1} max={90} onChange={value=>changeParams({review_days:value})}/><NumberField label="Días de cobertura del stock máximo" value={params.maximum_days} min={params.review_days} max={1095} onChange={value=>changeParams({maximum_days:value})}/><NumberField label="Plazo de llegada (días)" value={params.lead_days} min={0} max={180} onChange={value=>changeParams({lead_days:value})}/><label>Stock de seguridad<select value={params.use_safety_stock===false?"OFF":"ON"} onChange={e=>changeParams({use_safety_stock:e.target.value==="ON"})}><option value="ON">Con stock de seguridad</option><option value="OFF">Sin stock de seguridad</option></select></label>{params.use_safety_stock!==false&&<NumberField label="Nivel de servicio (%)" value={params.service_level} min={50} max={99.9} step={0.1} onChange={value=>changeParams({service_level:value})}/>}</div>
 <p className="small"><b>Stock mínimo = consumo diario × plazo de llegada{params.use_safety_stock!==false?" + stock de seguridad":""}.</b> {params.use_safety_stock===false?"Seguridad desactivada: no se añade colchón al mínimo, al punto de reposición, al máximo ni a la reserva de Almeiras.":"Seguridad activada: el colchón se incluye en el mínimo y en los objetivos derivados."}</p><div className="repl-formulas"><div className={params.target_mode==='POINT'?'chosen':''}><b>Punto de reposición</b><p>Stock mínimo + consumo diario × <strong>{params.review_days||'…'} días</strong></p></div><div className={params.target_mode==='MAXIMUM'?'chosen':''}><b>Stock máximo</b><p>Stock mínimo + consumo diario × <strong>{params.maximum_days||'…'} días</strong></p></div></div><p className="small"><b>A reponer = máximo entre 0 y (objetivo elegido − disponible previsto).</b> Disponible previsto = stock + pendiente de recibir − pendiente de servir. Se muestran dos propuestas: redondeada hacia arriba a unidades enteras y redondeada al múltiplo de EXIT. La redistribución toma como referencia la propuesta sin agrupación.</p><details className="repl-column-help"><summary>Significado de las columnas</summary><dl className="repl-column-definitions">{[
 ['Artículo / Del.','Código, descripción y delegación. Se pueden ordenar por separado desde Orden.'],
 ['Stock / Entrada +Trans / Salida +Trans','Stock físico de EXIT. Entrada = pendiente de recibir + tránsitos entrantes; salida = pendiente de servir + tránsitos salientes. Se agrupan por los almacenes activos marcados para stock de cada delegación. Datos guardados al calcular.'],
 ['Disp.','Disponible previsto = stock + entradas − salidas. Puede ser negativo. Las entradas aún no son stock físico.'],
 ['Cons./mes','Media diaria neta × 30 como referencia mensual en los cálculos nuevos. Media diaria = (todas las ventas − todas las devoluciones) ÷ días reales, incluyendo días sin ventas. Se muestra redondeada a unidades; los filtros y cálculos mantienen los decimales. Los cálculos anteriores conservan su método, explicado en Ver.'],
 ['Flag','Revisión del consumo según frecuencia, concentración y picos. No elimina ventas ni cambia automáticamente la propuesta. Orden: verde, ámbar, rojo; sin análisis al final.'],
 ['Mín.','Consumo diario del criterio × plazo de llegada + seguridad. Seguridad = Z del nivel de servicio × desviación diaria × raíz del plazo; cero si está desactivada.'],
 ['Punto','Mínimo + consumo diario del criterio × ciclo de reposición.'],
 ['Máx.','Mínimo + consumo diario del criterio × cobertura máxima. Mínimo, punto y máximo se muestran hacia arriba a unidades; la propuesta usa los valores precisos.'],
 ['Base','Máximo entre cero y (objetivo elegido − disponible previsto), redondeado hacia arriba a unidades. Se aplican las exclusiones configuradas.'],
 ['Múlt.','Necesidad ajustada al múltiplo de EXIT, mostrado debajo. Si falta o no es válido, indica Revisar.'],
 ['Almeiras · Desp.','Máximo entre cero y (stock disponible − reserva propia). La reserva protege el consumo propio durante plazo de llegada + días de reserva, más seguridad si está activada. Cubre compara con la necesidad conjunta del artículo sin contar varias veces el stock.'],
 ['Almeiras · Stock disp.','Stock físicamente libre = máximo entre cero y (stock físico de Almeiras − pendiente de servir). Antes de descontar su reserva propia. No suma lo pendiente de recibir. Ambas cifras se muestran hacia abajo a unidades; Sin datos no equivale a cero.'],
 ['Detalle','Valores precisos, variables y avisos. Ordenar por Detalle utiliza el número de avisos.'],
 ['Ordenación / fecha','Todo el resultado filtrado se ordena antes de paginar, por los valores precisos y el criterio elegido. Los campos sin datos quedan al final. Son cifras del cálculo guardado: ordenar no vuelve a consultar EXIT.']
 ].map(([label,help])=><div key={label}><dt>{label}</dt><dd>{help}</dd></div>)}</dl></details>
 <h2>3. Reposición e intercambio entre delegaciones</h2><div className="repl-actions"><NumberField label="Días de consumo que se reservan en Almeiras" value={params.central_reserve_days} min={1} max={365} onChange={value=>changeParams({central_reserve_days:value})}/><label className="repl-simple-check"><input type="checkbox" checked={params.exclude_no_consumption} onChange={e=>changeParams({exclude_no_consumption:e.target.checked})}/>No calcular reposición para destinos sin consumo neto en el periodo</label></div><p className="small">Disponible para despachar = stock físico de Almeiras − comprometido − reserva propia. La reserva cubre el consumo durante estos días y el plazo de llegada, más su seguridad. Se comprueba la suma de todas las delegaciones seleccionadas. Las entradas pendientes no se pueden despachar todavía.</p>
 <div className="repl-actions"><button className="primary" disabled={busy||!options} onClick={()=>void run()}>{jobActive(job)?'Cálculo en curso':busy?(phase||'Procesando…'):'Calcular reposición'}</button><span className="small">Límite: {options?.article_limit.toLocaleString('es-ES')||'…'} artículos</span></div><details><summary>Configurar límite de artículos</summary><div className="repl-actions"><label>Máximo de artículos<input type="number" min={1} max={options?.maximum_article_limit} value={limit} onChange={e=>setLimit(e.target.value)}/></label><button className="secondary" disabled={busy||!options||!Number.isInteger(Number(limit))||Number(limit)<1||Number(limit)>(options?.maximum_article_limit||0)} onClick={()=>void saveLimit()}>Guardar límite</button></div></details></fieldset></section>
 {job&&<section className="panel repl-progress" aria-label="Progreso del cálculo" aria-busy={jobActive(job)}><div className="repl-progress-heading"><b>{job.status==='COMPLETED'?'Cálculo terminado':job.status==='FAILED'?'Cálculo sin completar':job.status==='QUEUED'?'Esperando turno':'Calculando reposición'}</b><strong>{job.progress} %</strong></div><progress aria-label="Artículos guardados" max={100} value={job.progress}/><p role="status">{job.phase}</p><small>{job.total_articles?`${job.processed_articles.toLocaleString('es-ES')} de ${job.total_articles.toLocaleString('es-ES')} ${job.sequential_delegations?'cálculos artículo/delegación':'artículos'} guardados · ${job.completed_batches} de ${job.total_batches} bloques`:job.status==='COMPLETED'?'No hay artículos para la selección.':'Preparando la selección; todavía no ha terminado.'}</small>{jobActive(job)&&<p className="small">{job.sequential_delegations?'Cada delegación termina sus bloques de hasta 1.000 artículos antes de iniciar la siguiente.':'Bloques de hasta 1.000 artículos, con todas sus delegaciones.'} El resultado se publicará cuando estén completos todos los bloques. {calculation?'Debajo se mantiene el resultado anterior.':'La tabla aparecerá al terminar.'}</p>}{job.status==='FAILED'&&<p className="error">{job.error}</p>}</section>}
 {calculation&&<section aria-label="Resultado de reposición">{calculation.temporary_parameters.multiple_mode!=="NONE"&&<p className="repl-notice">Este cálculo guardado utilizaba un formato de despacho anterior. Recalcula para usar ambas propuestas y actualizar la referencia de redistribución.</p>}{dirty&&!jobActive(job)&&<p className="repl-notice">Has cambiado los parámetros. Pulsa Calcular reposición para actualizar el resultado.</p>}<div className="repl-result-heading"><div><h2>Resultado{resultDelegation?` · Delegación ${resultDelegation}`:""} · {calculation.temporary_parameters.target_mode==='MAXIMUM'?'Stock máximo':'Punto de reposición'} · {basisLabels[resultBasis]}</h2><p className="small">Datos de EXIT: {calculation.extraction_started_at?`${time(calculation.extraction_started_at)} — `:''}{time(calculation.captured_at)} · Ventas {calculation.filters.date_from} — {calculation.filters.date_to}</p></div><label>Formato Excel <select value={exportMode} onChange={e=>setExportMode(e.target.value)}><option value="simple">Simplificado · columnas de la tabla</option><option value="expanded">Ampliado · detalle completo</option></select></label><button className="secondary" disabled={exporting||loadingRows||!summary} onClick={()=>void download()}>{exporting?'Generando Excel…':'Descargar Excel filtrado'}</button></div><div className="repl-metrics">{[['articles_analyzed','Artículos'],['to_replenish','A reponer'],['central_covered','Cubiertos por Almeiras'],['central_attention','Reponer sin cobertura'],['overstock','Con sobrestock'],['without_movement','Sin consumo']].map(([key,label])=><div key={key}><span>{label}</span><b>{summary?fmt(summary[key]):'…'}</b></div>)}</div><p className="small">Excel simplificado: columnas visibles, con el mismo redondeo de la tabla. Entrada +Trans = pendiente de recibir + intercambios entrantes en tránsito. Salida +Trans = pendiente de servir + intercambios salientes en tránsito. Se agrupan mediante los almacenes activos para stock. Disponible previsto = stock + Entrada +Trans − Salida +Trans. Los cálculos antiguos mantienen sus datos hasta recalcular. Los contadores y el Excel incluyen todos los resultados filtrados, de todas las páginas. Los contadores de estados corresponden a combinaciones artículo/delegación. Las coberturas junto al disponible distinguen ambas propuestas conjuntas. El contador «Cubiertos» y el filtro de cobertura usan la propuesta sin agrupación en los cálculos nuevos; no se ha reservado ni asignado stock.</p>
 {(summary?.central_attention||0)>0&&<div className={`repl-stock-warning ${(summary?.central_no_stock||0)>0?'danger':'warning'}`} role={(summary?.central_no_stock||0)>0?'alert':'status'}><div><b>⚠ Reposición pendiente sin cobertura de Almeiras</b><p>Líneas a reponer: {summary?.central_no_stock||0} sin disponible · {summary?.central_insufficient||0} con cobertura insuficiente para el conjunto.</p><small>Se consideran existencias físicas tras compromisos y reserva propia. Las entradas pendientes no se pueden despachar.</small></div><button className="secondary" onClick={()=>{setCentralCoverage('UNCOVERED');setStockAlertFilter('ALL')}}>Ver pendientes sin cobertura</button></div>}
 <ConsumptionBasisPicker name="replenishment-result-basis" value={resultBasis} available={calculation.consumption_bases||[calculation.temporary_parameters.consumption_basis||'MEAN']} onChange={setResultBasis}/>{(calculation.consumption_bases||[]).length<3&&<p className="small">Este cálculo anterior solo incluye el criterio guardado. Genera un cálculo nuevo para disponer de las tres propuestas.</p>}<div className="toolbar repl-result-toolbar"><label>Delegación del resultado<select aria-label="Delegación del resultado" value={resultDelegation||'ALL'} onChange={e=>setResultDelegation(e.target.value==='ALL'?null:e.target.value)}>{calculation.filters.delegations.length>1&&<option value="ALL">Todas las delegaciones calculadas</option>}{calculation.filters.delegations.map(code=><option key={code} value={code}>{nodes.delegations.find(d=>d.code===code)?.name||`Delegación ${code}`}</option>)}</select></label><input aria-label="Buscar resultado" placeholder="Código o descripción" value={search} onChange={e=>setSearch(e.target.value)}/><label><input type="checkbox" checked={needed} onChange={e=>setNeeded(e.target.checked)}/>Solo a reponer</label><label>Atención desde Almeiras<select aria-label="Atención desde Almeiras" value={centralCoverage} onChange={e=>{setCentralCoverage(e.target.value);setStockAlertFilter('ALL')}}><option value="ALL">Todos</option><option value="COVERED">Se puede atender</option><option value="UNCOVERED">No se puede atender</option><option value="UNKNOWN">Disponibilidad sin confirmar</option></select></label><label><input type="checkbox" checked={overstockOnly} onChange={e=>setOverstockOnly(e.target.checked)}/>Solo sobrestock</label><label>Alerta de reposición<select aria-label="Alerta de reposición" value={stockAlertFilter} onChange={e=>{setStockAlertFilter(e.target.value);if(e.target.value!=='ALL')setCentralCoverage('ALL')}}><option value="ALL">Todas las líneas</option><option value="ATTENTION">A reponer sin cobertura</option><option value="NO_STOCK">Almeiras sin disponible</option><option value="INSUFFICIENT">Almeiras no cubre el conjunto</option><option value="UNKNOWN">Disponibilidad sin confirmar</option></select></label><label>Consumo<select value={consumption} onChange={e=>setConsumption(e.target.value)}><option value="ALL">Todos</option><option value="WITH">Con consumo</option><option value="WITHOUT">Sin consumo</option></select></label><NumberField label="Consumo mensual mínimo (filtro)" value={minimumMonthly} min={0} max={1e9} step={0.01} onChange={setMinimumMonthly}/><label>Consumo mensual máximo (filtro)<input aria-label="Consumo mensual máximo (filtro)" type="number" min={minimumMonthly} max={1e9} step={0.01} value={maximumMonthly} placeholder="Sin límite" onChange={e=>setMaximumMonthly(e.target.value)}/></label><small>Mínimo y máximo incluidos. Máximo vacío = sin límite. No modifica las cantidades calculadas.</small><label>Orden<select aria-label="Ordenar resultados por" value={sort} onChange={e=>{setSort(e.target.value);setDescending(false)}}>{sortFields.map(([key,label])=><option value={key} key={key}>{label}</option>)}</select></label><label>Sentido<select aria-label="Sentido de ordenación" value={descending?'desc':'asc'} onChange={e=>setDescending(e.target.value==='desc')}><option value="asc">Ascendente</option><option value="desc">Descendente</option></select></label></div><p className="small">Atención desde Almeiras: filtra las líneas a reponer de otras delegaciones. «Se puede atender» exige cubrir la necesidad conjunta sin consumir la reserva propia; «No se puede atender» incluye stock nulo o insuficiente. Los datos sin confirmar se muestran aparte. Se usa la propuesta base, sin múltiplos.</p><fieldset className="repl-flag-filters"><legend>Filtrar por banderas</legend><label><input type="checkbox" checked={!exceptionalityFlags.length} onChange={()=>setExceptionalityFlags([])}/>Todas</label>{[['HIGH','high','Roja · alta excepcionalidad'],['MEDIUM','medium','Ámbar · revisar recurrencia'],['LOW','low','Verde · sin señales'],['UNKNOWN','unknown','Gris · sin análisis o datos suficientes']].map(([value,tone,label])=><label key={value}><input type="checkbox" checked={exceptionalityFlags.includes(value)} onChange={e=>setExceptionalityFlags(current=>e.target.checked?[...current,value]:current.filter(flag=>flag!==value))}/><span className={`repl-exceptionality-${tone}`} aria-hidden="true">⚑</span> {label}</label>)}</fieldset>{invalidConsumptionRange&&<p className="error" role="alert">El consumo mensual máximo debe ser mayor o igual que el mínimo.</p>}{loadingRows&&<p role="status">Actualizando resultados…</p>}
 <p className="small" role="note"><b>Presentación:</b> mínimo, punto de reposición y máximo se muestran redondeados hacia arriba a unidades enteras (0,30 → 1). El consumo mensual se muestra redondeado a la unidad más cercana (26,64 → 27). En los nuevos cálculos es la media diaria neta × 30 como referencia mensual; se descuentan todas las devoluciones y la media diaria usa los días reales. El neto del periodo se consulta en el detalle. Las unidades de EXIT no se convierten. Almeiras muestra despachable / stock disponible antes de reserva, y se redondea hacia abajo a unidades enteras (39,107 → 39). «Ver datos» conserva el detalle decimal. El sobrestock se presenta sin decimales. Los cálculos mantienen su precisión interna; el detalle muestra los valores usados.</p><ExceptionalityLegend/><p className="small repl-stock-legend"><b>Alerta de reposición:</b> <span className="stock-no-stock">⚠ Rojo: sin disponible en Almeiras.</span> <span className="stock-insufficient">⚠ Ámbar: no alcanza para el conjunto.</span> Gris: disponibilidad sin confirmar. Solo se marcan líneas con cantidad a reponer.</p><details className="repl-column-help"><summary>Significado de las columnas</summary><p>Entrada: pendiente de recibir. Salida: pendiente de servir. Disp.: stock + entradas − salidas. Cons./mes: promedio mensual de referencia (media diaria neta × 30 en los nuevos cálculos). El detalle muestra todas las ventas, devoluciones y el neto del periodo. Mín., Punto y Máx.: objetivos de stock. Base: reposición sin agrupación. Múlt.: reposición con múltiplos EXIT. Disp. central: Almeiras disponible para despacho; «Cubre» comprueba la necesidad conjunta de las delegaciones. Pulsa «Ver» para consultar todos los datos y avisos del artículo.</p></details><div className="repl-results repl-compact repl-clean-results"><table><colgroup>{[22,3,4,4,4,5,6,4,4,4,4,5,5,10,6].map((width,index)=><col key={index} style={{width:`${width}%`}}/>)}</colgroup><thead><tr className="repl-column-groups"><th colSpan={2}>Artículo</th><th colSpan={3} className="repl-origin">Datos EXIT</th><th colSpan={6} className="repl-derived">Consumo y objetivos</th><th colSpan={2} className="repl-proposal">Reposición</th><th className="repl-central">Almeiras</th><th>Revisión</th></tr><tr>{[['Artículo','Código y descripción'],['Del.','Delegación'],['Stock','Stock físico'],['Entrada +Trans','Pendiente de recibir más intercambios entrantes en tránsito'],['Salida +Trans','Pendiente de servir más intercambios salientes en tránsito'],['Disp.','Disponible previsto: stock + entradas − salidas'],['Cons./mes','Promedio mensual de referencia: media diaria neta × 30; el detalle conserva ventas y devoluciones'],['Flag','Excepcionalidad: consulta la leyenda de colores'],['Mín.','Stock mínimo'],['Punto','Punto de reposición'],['Máx.','Stock máximo'],['Base','Cantidad a reponer sin agrupación'],['Múlt.','Cantidad a reponer con múltiplos EXIT'],['Almeiras','Despachable / stock disponible antes de reserva'],['Detalle','Avisos y datos completos']].map(([label,help],index)=><th key={label} title={help} aria-label={help} aria-sort={sort===['sku', 'delegation', 'stock', 'incoming', 'outgoing', 'inventory_position', 'monthly_mean', 'exceptionality', 'minimum_stock', 'replenishment_point', 'maximum_stock', 'quantity_without_multiple', 'quantity_with_exit_multiple', 'central_available', 'alerts'][index]?(descending?'descending':'ascending'):'none'} className={index>=2&&index<=4?'repl-origin':index>=5&&index<=10?'repl-derived':index===11||index===12?'repl-proposal':index===13?'repl-central':''}>{index===13?<div className="repl-central-pair">{sortButton('central_available','Desp.')}{sortButton('central_physical_available','Stock disp.')}</div>:sortButton(['sku', 'delegation', 'stock', 'incoming', 'outgoing', 'inventory_position', 'monthly_mean', 'exceptionality', 'minimum_stock', 'replenishment_point', 'maximum_stock', 'quantity_without_multiple', 'quantity_with_exit_multiple', 'central_available', 'alerts'][index],label)}</th>)}</tr></thead><tbody>{rows.map(row=><tr key={row.id} className={`${row.overstock?'repl-overstock-row':''} ${row.stock_alert&&row.stock_alert.code!=='NONE'?`repl-stock-row-${row.stock_alert.code}`:''}`}><td><button className="repl-article-link" onClick={()=>setSelected(row)}><b>{row.sku}</b><span title={row.description}>{row.description}</span></button><StockAlarm alert={row.stock_alert}/>{row.overstock&&<small className="repl-overstock-badge">Sobrestock: +{fmtExcess(row.excess_stock)}</small>}{row.no_consumption&&<small>Sin consumo en el periodo</small>}</td><td>{row.delegation==='00'?'Almeiras':row.delegation}</td>{(['stock','incoming','outgoing'] as const).map(key=><td key={key} className="repl-origin">{fmt(row[key])}</td>)}<td className="repl-derived">{fmt(row.inventory_position)}</td><td className="repl-derived">{fmtMonthly(row.monthly_mean??row.daily_mean*30)} <small>{row.unit_type}/mes</small></td><td className="repl-derived repl-consumption-analysis"><ExceptionalityFlag value={row.exceptionality} onReview={()=>setSelected(row)}/></td><td className="repl-derived">{row.statistic_available===false?'Revisar':fmtTarget(row.minimum_stock)}</td><td className="repl-derived">{row.statistic_available===false?'Revisar':fmtTarget(row.replenishment_point)}</td><td className="repl-derived">{row.statistic_available===false?'Revisar':fmtTarget(row.maximum_stock)}</td><td className="repl-proposal"><strong className="repl-final-quantity">{fmt(row.quantity_without_multiple??row.final_quantity)}</strong></td><td className="repl-proposal"><strong className={`repl-final-quantity ${row.quantity_with_exit_multiple==null?'repl-review-value':''}`} title={row.quantity_with_exit_multiple==null?'Revisar el múltiplo de EXIT en Ver datos':undefined}>{row.quantity_with_exit_multiple===undefined?"Recalcular":row.quantity_with_exit_multiple===null?"Revisar":fmt(row.quantity_with_exit_multiple)}</strong><small title="Múltiplo de despacho de EXIT">× {fmt(row.exit_multiple)}</small></td><td className="repl-central"><div className="repl-central-pair"><button className={`repl-central-button ${row.central_can_supply?'covered':'short'}`} onClick={()=>setSelected(row)}>{fmtDispatch(row.central_available)}{row.delegation==='00'?<small>{centralAvailabilityLabel(row.central_available)}</small>:<><small title={`Cobertura conjunta sin agrupación: ${coverageLabel(row.central_covers_without_multiple,row.quantity_without_multiple)}`}>Base: {compactCoverage(row.central_covers_without_multiple,row.quantity_without_multiple)}</small><small title={`Cobertura conjunta con múltiplos EXIT: ${coverageLabel(row.central_covers_with_exit_multiple,row.quantity_with_exit_multiple)}`}>Múlt.: {compactCoverage(row.central_covers_with_exit_multiple,row.quantity_with_exit_multiple)}</small></>}</button><span className="repl-central-physical" title="Stock de Almeiras menos pendiente de servir, antes de reserva propia">{fmtDispatch(row.central_physical_available)}</span></div></td><td><button className="repl-notes-button" aria-label={`Ver datos y avisos de ${row.sku}`} onClick={()=>setSelected(row)}>Ver{row.recommendations.length?` (${row.recommendations.length})`:''}</button></td></tr>)}{!loadingRows&&!rows.length&&<tr><td colSpan={15}>No hay materiales con estos filtros.</td></tr>}</tbody></table></div><div className="repl-actions"><button className="secondary" disabled={page<=1||loadingRows} onClick={()=>setPage(value=>value-1)}>Anterior</button><span>{total} resultados · Página {page} de {Math.max(1,Math.ceil(total/50))}</span><button className="secondary" disabled={page*50>=total||loadingRows} onClick={()=>setPage(value=>value+1)}>Siguiente</button></div></section>}
 </div>
 <div id="repl-panel-redistribution" role="tabpanel" aria-labelledby="repl-tab-redistribution" hidden={tab!=='redistribution'}>{savedOpened&&<ReplenishmentSaved classifications={nodes} revision={`${job?.id||""}:${job?.status||""}`} onOpen={openSaved} disabled={busy||restoring}/>}</div>
 <div id="repl-panel-procurement" role="tabpanel" aria-labelledby="repl-tab-procurement" hidden={tab!=='procurement'}>{purchaseOpened&&options&&<Procurement classifications={nodes} serverDate={options.server_date}/>}</div>
 {selected&&<MaterialData row={selected} scenarioId={calculation!.id} onClose={()=>setSelected(null)}/>}
 </section>
}
function StockAlarm({alert}:{alert?:StockAlert}){return !alert||alert.code==='NONE'?null:<small className={`repl-stock-badge repl-stock-badge-${alert.code}`}>⚠ {alert.label}</small>}
function centralAvailabilityLabel(value:number|null|undefined){return value==null||!Number.isFinite(value)?'Disponibilidad sin confirmar':value<=0?'Sin disponible para despacho':value<1?'Menos de 1 unidad disponible':'Para otras delegaciones'}
function compactCoverage(covered:boolean|null|undefined,quantity:number|null|undefined){return quantity===null?'Revisar':quantity===0?'Sin pedido':covered==null?'Sin datos':covered?'Cubre':'No cubre'}
function coverageLabel(covered:boolean|null|undefined,quantity:number|null|undefined){return quantity===null?'Revisar múltiplo':quantity===0?'Sin necesidad':covered==null?'Sin cobertura confirmada':covered?'Cubre conjunto':'No cubre conjunto'}
function NumberField({label,value,min,max,step=1,onChange}:{label:string;value:number;min:number;max:number;step?:number;onChange:(n:number)=>void}){return <label>{label}<input type="number" min={min} max={max} step={step} value={Number.isNaN(value)?'':value} onChange={e=>onChange(e.target.value===''?NaN:Number(e.target.value))}/></label>}
function MaterialData({row,scenarioId,onClose}:{row:Row;scenarioId:string;onClose:()=>void}){
 const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();return()=>ref.current?.close()},[]);
 return createPortal(<dialog ref={ref} className="repl-dialog" aria-labelledby="repl-data-title" onCancel={e=>{e.preventDefault();onClose()}}><header><div><small>{row.sku} · Delegación {row.delegation}</small><h2 id="repl-data-title">{row.description}</h2></div><button className="ghost" aria-label="Cerrar detalle" onClick={onClose}>×</button></header><section><StockAlarm alert={row.stock_alert}/><h3>Cómo se obtiene la reposición</h3><p>Unidad de EXIT: <b>{row.unit_type||"Sin unidad"}</b>. No se ha convertido la cantidad. Campo de origen: {row.unit_source||"No registrado en este cálculo"}.</p><p>Ventas: <b>{fmt(row.gross_sales)}</b> − devoluciones: <b>{fmt(row.returns)}</b> = neto del periodo: <b>{fmt(row.gross_sales-row.returns)} {row.unit_type}</b> · {row.observed_days} días.</p><p>Media diaria guardada: <b>{fmt(row.daily_mean)} {row.unit_type}/día</b>. {row.consumption_method==='NET_PERIOD_V2'?'Neto del periodo ÷ días reales, incluyendo días sin ventas y devoluciones con signo.':'Cálculo anterior: conserva la fórmula mensual normalizada y el límite diario a cero. Genera un cálculo nuevo para aplicar el neto con todas las devoluciones.'}</p>{row.monthly_consumption&&<details><summary>Ver ventas y consumo por mes</summary><table><thead><tr><th>Mes</th><th>Días incluidos / mes</th><th>Vendido</th><th>Devuelto</th><th>Neto guardado</th><th>{row.consumption_method==='NET_PERIOD_V2'?'Media diaria del mes':'Consumo mensual normalizado'}</th></tr></thead><tbody>{row.monthly_consumption.map(month=><tr key={month.month}><td>{month.month}</td><td>{month.observed_days} / {month.calendar_days}</td><td>{fmt(month.sold)}</td><td>{fmt(month.returned)}</td><td>{fmt(month.consumption)}</td><td>{fmt(row.consumption_method==='NET_PERIOD_V2'?month.daily_mean??month.consumption/month.observed_days:month.monthly_consumption)}{month.estimated?' · estimado':''}</td></tr>)}</tbody></table><p>{row.consumption_method==='NET_PERIOD_V2'?'La media del periodo = suma de todos los netos ÷ suma de días incluidos. No se promedian las medias mensuales ni se proyectan meses incompletos.':'Método anterior: promedio de meses normalizados ÷ 30. Se conserva por trazabilidad.'} Mediana y moda usan solo días con neto positivo.</p></details>}<p>{row.parameters.use_safety_stock===false?"Sin stock de seguridad: seguridad = ":<>Seguridad = ({fmt(row.calculation.z)} × {fmt(row.daily_std)} × √({row.parameters.lead_days})) = </>}<b>{fmt(row.safety_stock)}</b>.</p><p>Mínimo = ({fmt(row.daily_reference??row.daily_mean)} × {row.parameters.lead_days}{row.parameters.use_safety_stock!==false?` + ${fmt(row.safety_stock)}`:""}) = <b>{fmt(row.minimum_stock)}</b>.</p><p>Punto de reposición = ({fmt(row.minimum_stock)} + {fmt(row.daily_reference??row.daily_mean)} × {row.parameters.review_days}) = <b>{fmt(row.replenishment_point)}</b>.</p><p>Stock máximo = ({fmt(row.minimum_stock)} + {fmt(row.daily_reference??row.daily_mean)} × {row.parameters.maximum_days}) = <b>{fmt(row.maximum_stock)}</b>.</p><p>Criterio elegido: <b>{basisLabels[row.parameters.consumption_basis||'MEAN']}</b>. Base diaria utilizada: <b>{fmt(row.daily_reference??row.daily_mean)} {row.unit_type}/día</b>.</p><p>Objetivo elegido: <b>{row.parameters.target_mode==='MAXIMUM'?'Stock máximo':'Punto de reposición'} · {fmt(row.target_stock)}</b>. Disponible previsto: {fmt(row.inventory_position)}. A reponer sin agrupación: <b>{fmt(row.quantity_without_multiple??row.final_quantity)}</b>. Con múltiplos de EXIT: <b>{row.quantity_with_exit_multiple===undefined?'Recalcular':row.quantity_with_exit_multiple===null?'Revisar':fmt(row.quantity_with_exit_multiple)}</b> (múltiplo {fmt(row.exit_multiple)}).</p>{row.no_consumption&&row.parameters.exclude_no_consumption&&<p>Reposición a cero porque se ha seleccionado no reponer artículos sin consumo.</p>}{row.overstock&&<p className="repl-overstock-badge">Sobrestock previsto: {fmtExcess(row.excess_stock)} por encima del máximo.</p>}</section>{row.interchanges_included&&<section><h3>Entradas y salidas con intercambios en tránsito</h3><p>Entrada +Trans: pendiente de recibir {fmt(row.incoming_exit)} + intercambios entrantes {fmt(row.incoming_transit)} = <b>{fmt(row.incoming)}</b>.</p><p>Salida +Trans: pendiente de servir {fmt(row.outgoing_exit)} + intercambios salientes {fmt(row.outgoing_transit)} = <b>{fmt(row.outgoing)}</b>.</p><p className="small">Se agrupan por los almacenes activos marcados para stock de cada delegación. Origen: CodigoAlmacen; destino: AlmacenContrapartida. Solo estado Transito y tipo T. Las entradas pendientes no se consideran stock físico despachable.</p></section>}<ReplenishmentHistory endpoint={`${base}/simulations/${scenarioId}/results/${row.id}?consumption_basis=${row.parameters.consumption_basis||'MEAN'}`} unit={row.unit_type}/><section><h3>Almeiras · cómo se obtiene el disponible</h3><p>Fuente: VIS_EX_StockVentasDelegacion, IdDelegacion 00. Stock físico = UnidadSaldo; comprometido = PendienteServir + intercambios salientes en tránsito. Disponible para despacho = máximo entre 0 y (stock físico − comprometido − reserva propia). PendienteRecibir se muestra, pero no se suma al disponible.</p><dl className="repl-parameter-values">{[['Stock físico',row.central_stock],['Stock disponible antes de reserva',row.central_physical_available],['Por servir (comprometido)',row.central_outgoing],['Pendiente de recibir (no despachable)',row.central_incoming],['Consumo mensual propio',row.central_monthly_consumption],['Reserva propia',row.central_reserve],['Disponible para despachar',row.central_available],['Necesidad conjunta sin agrupación',row.central_total_without_multiple],['Necesidad conjunta con múltiplos EXIT',row.central_total_with_exit_multiple]].map(([label,value])=><div key={String(label)}><dt>{label}</dt><dd>{fmt(value as number|null)}</dd></div>)}</dl><p>Reserva = [consumo diario propio × (plazo de llegada + {row.central_reserve_days} días de reserva){row.parameters.use_safety_stock!==false?" + seguridad propia":""}]. {row.parameters.use_safety_stock===false?"La seguridad propia es cero por la opción seleccionada.":"La seguridad propia = Z × desviación diaria de Almeiras × √(plazo de llegada)."} Los días de reserva cubren consumo medio y no se suman al plazo de seguridad.</p>{row.delegation!=='00'&&<p>Sin agrupación: <b>{coverageLabel(row.central_covers_without_multiple,row.quantity_without_multiple)}</b>. Con múltiplos EXIT: <b>{coverageLabel(row.central_covers_with_exit_multiple,row.quantity_with_exit_multiple)}</b>.</p>}<p className="small">El stock se cuenta una sola vez por artículo. No se ha realizado ninguna reserva o traslado real.</p></section>{row.recommendations.length>0&&<section><h3>Avisos</h3>{row.recommendations.map((note,index)=><p key={index}>{note.reason}</p>)}</section>}<footer><button className="primary" onClick={onClose}>Cerrar</button></footer></dialog>,document.body)
}
